// 1. Validação defensiva do payload
const rawInput = $input.first().json.body || $input.first().json || {};
const rawFrom = rawInput.from;
const rawMensagem = rawInput.mensagem;

if (!rawFrom || !rawMensagem || typeof rawMensagem !== 'string' || rawMensagem.trim().length === 0) {
  return [{
    json: {
      isValid: false,
      errorCode: 'INVALID_PAYLOAD',
      errorMessage: "Os campos 'from' (telefone/ID) e 'mensagem' (texto não vazio) são obrigatórios.",
      received: rawInput
    }
  }];
}

const usuario = String(rawFrom).replace(/\D/g, '') || String(rawFrom).trim();
const textoNormalizado = rawMensagem
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .trim();

return [{
  json: {
    isValid: true,
    usuario,
    texto: textoNormalizado,
    mensagemOriginal: rawMensagem.trim(),
    receivedAt: new Date().toISOString()
  }
}];

// Motor de Classificação Semântica de Intenções
const { texto, usuario, mensagemOriginal, receivedAt } = $input.first().json;

const intencoes = {
  SUPORTE_URGENTE: {
    termos: ['ajuda', 'socorro', 'urgente', 'problema', 'defeito', 'quebrou', 'falha', 'erro', 'travou'],
    resposta: "Olá! Identificamos que você precisa de suporte urgente. Nossa equipe técnica já foi acionada para te atender com prioridade máxima."
  },
  COMERCIAL_VENDAS: {
    termos: ['comprar', 'preco', 'valor', 'orcamento', 'catalogo', 'produto', 'quanto custa', 'promocao'],
    resposta: "Olá! Ficamos muito felizes pelo seu interesse em nossas soluções. Um de nossos consultores comerciais entrará em contato em instantes."
  },
  CANCELAMENTO: {
    termos: ['cancelar', 'estorno', 'reembolso', 'devolucao', 'desistir'],
    resposta: "Sentimos muito que queira cancelar. Seu atendimento foi priorizado junto à nossa equipe de retenção."
  }
};

let intencaoIdentificada = 'DUVIDA_GERAL';
let resposta = "Mensagem recebida. Em breve retornaremos com todas as informações.";
let confianca = 0.70;
let termosCasados = [];

for (const [intencao, config] of Object.entries(intencoes)) {
  const matches = config.termos.filter(t => texto.includes(t));
  if (matches.length > 0) {
    intencaoIdentificada = intencao;
    resposta = config.resposta;
    termosCasados = matches;
    confianca = Math.min(0.98, 0.75 + (matches.length * 0.1));
    break;
  }
}

return [{
  json: {
    usuario,
    resposta,
    mensagemOriginal,
    intencao: intencaoIdentificada,
    confianca,
    termosCasados,
    receivedAt,
    processedAt: new Date().toISOString()
  }
}];

